#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <cctype>

using namespace std;

/**
 * Problem: 10531 - Zipf's Law
 * 
 * 解題思路：
 * 1. 給定一個正整數 n，找出在一段文本中恰好出現 n 次的所有單詞。
 * 2. 單詞定義：連續的字母序列，由非字母字符分隔。
 * 3. 忽略大小寫，輸出時統一使用小寫。
 * 4. 文本以 "EndOfText" 結束。
 * 5. 按字典序輸出滿足條件的單詞，若無則輸出 "There is no such word."。
 * 6. 每組測試數據之間輸出一行空行。
 */

void process_line(string& line, map<string, int>& counts) {
    string word = "";
    for (char c : line) {
        if (isalpha(c)) {
            word += (char)tolower(c);
        } else {
            if (!word.empty()) {
                counts[word]++;
                word = "";
            }
        }
    }
    if (!word.empty()) {
        counts[word]++;
    }
}

int main() {
    int n;
    bool first_case = true;
    while (cin >> n) {
        if (!first_case) cout << endl;
        first_case = false;

        map<string, int> counts;
        string line;
        while (cin >> line && line != "EndOfText") {
            process_line(line, counts);
            // 由於 cin >> line 會跳過空白，可能導致單詞被切斷
            // 但題目說單詞由非字母分隔，cin 讀取一行或一個連續字符串都可以，只要我們手動解析非字母即可
            // 不過 cin >> line 會在空格處停止，如果一個單詞包含非字母但不是空格（如 "abc.def"）
            // cin >> line 讀入 "abc.def"，解析後得到 "abc" 和 "def"。這是正確的。
        }

        vector<string> result;
        for (auto const& [word, freq] : counts) {
            if (freq == n) {
                result.push_back(word);
            }
        }

        if (result.empty()) {
            cout << "There is no such word." << endl;
        } else {
            sort(result.begin(), result.end());
            for (const string& w : result) {
                cout << w << endl;
            }
        }
    }
    return 0;
}

